body:
OK, I was able to reproduce with the simple following API calls:

```
POST logs-manual-default/_doc
{
  "message": "test"
}

POST logs-manual-default/_search
{
  "size": 0,
  "track_total_hits": false,
  "aggs": {
    "categories": {
      "categorize_text": {
        "field": "message",
        "size": 1000
      },
      "aggs": {
        "histogram": {
          "date_histogram": {
            "field": "@timestamp",
            "fixed_interval": "1h",
            "extended_bounds": {
              "min": "now-2d",
              "max": "now"
            }
          }
        },
        "change": {
          "change_point": {
            "buckets_path": "histogram>_count"
          }
        }
      }
    }
  }
}
```
